package fraymus.workspace;

import org.json.*;
import java.nio.*;
import java.nio.file.*;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;

/** Shared read interface; source-owned clocks/coordinates never become each other's state. */
final class SpatialRuntime040 {
    static final String VERSION="fraynix.shared-spatial-040-v1";
    private final Path file;private final WorldLedger worlds;private final WorldNativeStore nativeWorld;private final TabletopStore tabletop;private final KnowledgeStore knowledge;private final EmbeddedGameClient game;
    private final LinkedHashMap<String,JSONObject> cache=new LinkedHashMap<>();private final Set<String> pins=new HashSet<>();private final Map<String,JSONObject> rasters=new HashMap<>();
    private JSONObject state;
    SpatialRuntime040(Path project,WorldLedger worlds,WorldNativeStore nativeWorld,TabletopStore tabletop,KnowledgeStore knowledge,EmbeddedGameClient game)throws Exception{
        this.file=project.resolve("spatial-runtime-040/state.json");this.worlds=worlds;this.nativeWorld=nativeWorld;this.tabletop=tabletop;this.knowledge=knowledge;this.game=game;
        state=new JSONObject().put("selectedId","").put("view","all");
        if(Files.exists(file)){if(Files.size(file)>100000)throw new IllegalStateException("Spatial configuration exceeds budget");var e=new JSONObject(Files.readString(file));if(!VERSION.equals(e.getString("schema"))||!WorldFrames.hash(e.getJSONObject("state")).equals(e.getString("sha256")))throw new IllegalStateException("Spatial configuration checksum differs; original preserved");state=e.getJSONObject("state");SpatialScene.keys(state,"selectedId","view","binding");if(!SpatialProjection040.VIEWS.contains(state.getString("view"))&&!state.getString("view").equals("all"))throw new IllegalStateException("Unknown saved camera");}
    }
    private void save()throws Exception{Files.createDirectories(file.getParent());try(var channel=FileChannel.open(file.resolveSibling("state.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);var lock=channel.lock()){byte[] bytes=new JSONObject().put("schema",VERSION).put("state",state).put("sha256",WorldFrames.hash(state)).toString().getBytes(StandardCharsets.UTF_8);var pending=file.resolveSibling("state.pending.json");try(var out=FileChannel.open(pending,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,StandardOpenOption.WRITE)){var b=ByteBuffer.wrap(bytes);while(b.hasRemaining())out.write(b);out.force(true);}Files.move(pending,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}}
    synchronized JSONObject state()throws Exception{return WorldFrames.copy(state).put("worlds",worlds.list()).put("game",game.status()).put("schema",VERSION);}
    synchronized JSONObject bind(JSONObject in)throws Exception{
        SpatialScene.keys(in,"kind","worldId","observationRunId");String kind=in.getString("kind");JSONObject binding;
        if(kind.equals("world")){String id=in.getString("worldId");worlds.observe(id);binding=new JSONObject().put("kind",kind).put("worldId",id);if(in.has("observationRunId")&&!in.getString("observationRunId").isBlank()){var r=tabletop.read(in.getString("observationRunId"));if(!r.getJSONObject("nativeBinding").getString("worldId").equals(id))throw new IllegalArgumentException("Observation belongs to another native world");binding.put("observationRunId",r.getString("id"));}}
        else if(kind.equals("game")){if(in.has("worldId")||in.has("observationRunId"))throw new IllegalArgumentException("Game binding cannot accept native or camera IDs");var actual=game.spatial();binding=new JSONObject().put("kind",kind).put("sessionId",actual.getJSONObject("state").getString("sessionId"));}
        else throw new IllegalArgumentException("Choose world or open game runtime");
        if(!state.has("binding")||!state.getJSONObject("binding").similar(binding))state.put("selectedId","");state.put("binding",binding);var first=build();String chosen="";if(binding.has("observationRunId"))chosen=tabletop.read(binding.getString("observationRunId")).getString("bodyId");else if(kind.equals("game"))chosen=first.getJSONObject("source").getJSONObject("player").optString("id","");if(chosen.isBlank())for(Object raw:first.getJSONArray("entities")){var e=(JSONObject)raw;if(e.optBoolean("dynamic",false)){chosen=e.getString("id");break;}}state.put("selectedId",chosen);save();return read();
    }
    static JSONObject gameFrame(JSONObject actual){
        var s=actual.getJSONObject("state");var rows=actual.getJSONArray("entities");if(rows.length()>4096)throw new IllegalStateException("Game entity budget exceeded");var entities=new JSONArray();var ids=new HashSet<String>();
        for(Object raw:rows){var source=(JSONObject)raw;String id=source.getString("id");UUID.fromString(id);if(!ids.add(id))throw new IllegalStateException("Duplicate game identity");var e=new JSONObject().put("id",id).put("label",source.optString("label","")).put("components",source.getJSONArray("components")).put("dynamic",source.has("body")&&!source.getJSONObject("body").getString("type").equalsIgnoreCase("Static")).put("source",WorldFrames.copy(source));
            if(source.has("position")){var p=PlaneCalibration.point(source.getJSONArray("position"));var size=PlaneCalibration.point(source.getJSONArray("signedScale"));double rad=Math.toRadians(SpatialProjection040.finite(source.getDouble("rotationDeg"),-1e8,1e8));e.put("position",new double[]{p[0],p[1],0}).put("rotation",new double[]{0,0,Math.sin(rad/2),Math.cos(rad/2)}).put("size",new double[]{Math.abs(size[0]),Math.abs(size[1]),0}).put("renderLayer",source.getInt("renderLayer"));if(Math.abs(size[0])>1e-9&&Math.abs(size[1])>1e-9&&source.has("sprite")&&!source.getBoolean("dead"))e.put("shape","quad");}
            entities.put(e);
        }
        var camera=actual.getJSONObject("camera");var p=camera.getJSONArray("position");var span=camera.getJSONArray("span");for(int i=0;i<2;i++)SpatialProjection040.finite(span.getDouble(i),.001,20000);
        return new JSONObject().put("schema",VERSION).put("source",new JSONObject().put("kind","game").put("sessionId",s.getString("sessionId")).put("tick",s.getLong("tick")).put("frameSequence",s.getLong("frameSequence")).put("units","legacy-game-unit").put("dimensions",2).put("coordinateFrame","game-xy; geometry lies on z=0; no physical depth inferred").put("originalRasterSha256",actual.getString("pngSha256")).put("player",s.optJSONObject("player",new JSONObject())).put("continuous",s.getBoolean("continuous")))
            .put("entities",entities).put("focus",new JSONObject().put("center",new double[]{p.getDouble(0)+span.getDouble(0)/2,p.getDouble(1)+span.getDouble(1)/2,0}).put("span",span.getDouble(1)).put("spanX",span.getDouble(0))).put("limits",actual.getString("scope"));
    }
    static JSONObject nativeFrame(JSONObject observed,JSONObject live){
        var committed=observed.getJSONObject("frame");var source=WorldFrames.scene(committed);var objects=source.getJSONArray("objects");boolean pending=observed.has("pending"),active=pending&&live.has("current")&&live.optString("id").equals(observed.getJSONObject("pending").getString("runId"));
        long tick=committed.getLong("elapsedTicks");if(active){objects=live.getJSONObject("current").getJSONArray("objects");tick+=live.optJSONObject("sample",new JSONObject()).optLong("tick",0);}
        var rows=new JSONArray();var ids=new HashSet<String>();double[] low={Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY,Double.POSITIVE_INFINITY},high={-Double.POSITIVE_INFINITY,-Double.POSITIVE_INFINITY,-Double.POSITIVE_INFINITY};
        for(Object raw:objects){var o=(JSONObject)raw;String id=o.getString("id");if(!ids.add(id))throw new IllegalStateException("Duplicate native identity");var definition=SpatialScene.object(source,id);var e=new JSONObject().put("id",id).put("label",definition.getString("label")).put("sourceId",definition.getString("sourceId")).put("shape","box").put("position",o.getJSONArray("position")).put("rotation",o.getJSONArray("rotation")).put("size",definition.getJSONArray("size")).put("dynamic",definition.getDouble("massKg")>0).put("properties",new JSONObject().put("massKg",definition.getDouble("massKg")).put("friction",definition.getDouble("friction")).put("source",source.getJSONObject("source")));
            for(String key:List.of("velocity","angularVelocity"))if(o.has(key))e.put(key,o.get(key));rows.put(e);
            if(e.getBoolean("dynamic"))for(Object point:SpatialProjection040.corners(e)){var a=(JSONArray)point;for(int k=0;k<3;k++){low[k]=Math.min(low[k],a.getDouble(k));high[k]=Math.max(high[k],a.getDouble(k));}}
        }
        if(rows.length()!=source.getJSONArray("objects").length())throw new IllegalStateException("Native snapshot lost source identities");double[] center=new double[3];double span=2;for(int i=0;i<3;i++){center[i]=(low[i]+high[i])/2;span=Math.max(span,(high[i]-low[i])*1.5);}
        return new JSONObject().put("schema",VERSION).put("source",new JSONObject().put("kind","world").put("worldId",observed.getString("worldId")).put("revision",observed.getInt("expectedRevision")).put("headHash",observed.getString("expectedHash")).put("tick",tick).put("units","m").put("dimensions",3).put("coordinateFrame","right-handed-y-up").put("phase",active?"uncommitted-native-attempt":"committed-world-head").put("pendingOwned",pending).put("livePendingAvailable",active).put("sourceSha256",source.getString("sourceSha256")).put("pending",pending?WorldFrames.copy(observed.getJSONObject("pending")):JSONObject.NULL))
            .put("entities",rows).put("focus",new JSONObject().put("center",center).put("span",span)).put("limits","Source-qualified native simulation. Declared properties are not physical observations; viewing/selecting cannot actuate this world.");
    }
    private static JSONObject stamp(JSONObject n){var out=new JSONObject().put("headHash",n.getString("expectedHash"));if(n.has("pending"))out.put("pending",n.getJSONObject("pending"));return out;}
    private JSONObject build()throws Exception{
        if(!state.has("binding"))throw new IllegalStateException("Choose a persistent world or explicitly open and link the game");var b=state.getJSONObject("binding");JSONObject frame,raster=null;
        if(b.getString("kind").equals("game")){var actual=game.spatial();if(!actual.getJSONObject("state").getString("sessionId").equals(b.getString("sessionId")))throw new IllegalStateException("Game session changed; explicitly link the new session");frame=gameFrame(actual);raster=new JSONObject().put("pngBase64",actual.getString("pngBase64")).put("pngSha256",actual.getString("pngSha256"));}
        else{var first=worlds.observe(b.getString("worldId"));var live=nativeWorld.snapshot();var last=worlds.observe(b.getString("worldId"));if(!stamp(first).similar(stamp(last)))throw new IllegalStateException("World ownership/revision changed during read; refresh");frame=nativeFrame(first,live);
            if(b.has("observationRunId")){var run=tabletop.read(b.getString("observationRunId"));var facts=tabletop.understanding(run.getString("id"));var observation=new JSONObject().put("runId",run.getString("id")).put("bodyId",run.getString("bodyId")).put("frameId","mat:"+facts.getString("geometrySha256")).put("geometrySha256",facts.getString("geometrySha256")).put("codeSha256",facts.getString("codeSha256")).put("label",facts.getString("target")).put("labelSource",facts.getString("labelSource")).put("geometry",run.getJSONObject("geometry").getJSONObject("definition")).put("dimensions",2).put("units","m").put("heightKnown",false).put("alignedToNative",false).put("nativeStale",facts.getBoolean("nativeStale")).put("status",facts.getString("status")).put("limits",facts.getString("limits"));
                if(!facts.isNull("latest")){var row=facts.getJSONObject("latest");observation.put("estimate",row.getJSONObject("estimate")).put("imageSha256",row.getJSONObject("frame").getString("imageSha256")).put("sourceSeconds",row.getJSONObject("frame").getDouble("seconds")).put("receivedAt",row.getString("receivedAt")).put("ordinal",row.getInt("ordinal"));}
                frame.put("observationPlane",observation);
            }
        }
        var associations=new JSONArray();for(Object raw:knowledge.state().getJSONArray("objects")){var o=(JSONObject)raw;var a=o.getJSONObject("nativeAssociation");if(b.getString("kind").equals("world")&&a.getString("worldId").equals(b.getString("worldId")))associations.put(new JSONObject().put("knowledgeId",o.getString("id")).put("bodyId",a.getString("bodyId")).put("label",o.getString("label")).put("category",o.getString("category")).put("labelSource",o.getString("labelSource")));}
        frame.put("associations",associations).put("selectedId",state.getString("selectedId"));frame=WorldFrames.copy(frame);String hash=WorldFrames.hash(frame);frame.put("snapshotHash",hash);cache.put(hash,WorldFrames.copy(frame));if(raster!=null)rasters.put(hash,raster);
        while(cache.size()>16){String oldest=cache.keySet().stream().filter(h->!pins.contains(h)&&!h.equals(hash)).findFirst().orElseThrow();cache.remove(oldest);rasters.remove(oldest);}return frame;
    }
    synchronized JSONObject read()throws Exception{return WorldFrames.copy(build());}
    synchronized JSONObject cached(String hash){var frame=cache.get(hash);if(frame==null)throw new IllegalStateException("Snapshot expired or process restarted; read again");var unsigned=WorldFrames.copy(frame);unsigned.remove("snapshotHash");if(!WorldFrames.hash(unsigned).equals(hash))throw new IllegalStateException("Cached spatial snapshot changed");return WorldFrames.copy(frame);}
    synchronized JSONObject pin(String hash){cached(hash);if(!pins.contains(hash)&&pins.size()>=2)throw new IllegalStateException("Two pinned task snapshots already in use");pins.add(hash);return new JSONObject().put("pinned",hash);}
    synchronized JSONObject release(String hash){pins.remove(hash);return new JSONObject().put("released",hash);}
    synchronized JSONObject view(JSONObject args){SpatialScene.keys(args,"snapshotHash","camera");return SpatialProjection040.project(cached(args.getString("snapshotHash")),args.getJSONObject("camera"));}
    synchronized JSONObject pick(JSONObject args)throws Exception{SpatialScene.keys(args,"snapshotHash","camera","x","y");var f=cached(args.getString("snapshotHash"));var input=WorldFrames.copy(args);input.remove("snapshotHash");var hit=SpatialProjection040.pick(f,input);if(!hit.getString("id").isBlank())select(f.getString("snapshotHash"),hit.getString("id"));return hit;}
    synchronized JSONObject select(String hash,String id)throws Exception{var f=cached(hash);boolean found=false;for(Object raw:f.getJSONArray("entities"))if(((JSONObject)raw).getString("id").equals(id))found=true;if(!found)throw new IllegalArgumentException("Entity is absent from this exact source snapshot");var current=build();if(!current.getJSONObject("source").getString("kind").equals(f.getJSONObject("source").getString("kind")))throw new IllegalStateException("Selected source changed; refresh");for(String key:List.of("worldId","sessionId"))if(f.getJSONObject("source").has(key)&&!f.getJSONObject("source").getString(key).equals(current.getJSONObject("source").optString(key)))throw new IllegalStateException("Source identity changed; refresh");for(String key:List.of("tick","headHash","revision","phase","pending","originalRasterSha256"))if((f.getJSONObject("source").has(key)||current.getJSONObject("source").has(key))&&!new JSONObject().put("v",f.getJSONObject("source").opt(key)==null?JSONObject.NULL:f.getJSONObject("source").opt(key)).similar(new JSONObject().put("v",current.getJSONObject("source").opt(key)==null?JSONObject.NULL:current.getJSONObject("source").opt(key))))throw new IllegalStateException("Source clock/revision changed; refresh before selecting (pause a running game)");state.put("selectedId",id);save();return new JSONObject().put("id",id).put("sourceSnapshotHash",hash);}
    synchronized JSONObject config(String view)throws Exception{if(!SpatialProjection040.VIEWS.contains(view)&&!view.equals("all"))throw new IllegalArgumentException("Unknown view");state.put("view",view);save();return new JSONObject().put("view",view);}
    synchronized JSONObject raster(String hash)throws Exception{cached(hash);var image=rasters.get(hash);if(image==null)throw new IllegalArgumentException("This source has no original game raster");if(!PerceptionStore.hash(Base64.getDecoder().decode(image.getString("pngBase64"))).equals(image.getString("pngSha256")))throw new IllegalStateException("Cached original raster checksum differs");return WorldFrames.copy(image);}
    static JSONObject summary(JSONObject f){var rows=new JSONArray();for(Object raw:f.getJSONArray("entities")){var e=(JSONObject)raw;if(e.getString("id").equals(f.getString("selectedId"))){var copy=WorldFrames.copy(e);copy.remove("source");rows.put(copy);break;}}for(Object raw:f.getJSONArray("entities")){var e=(JSONObject)raw;if(!e.getString("id").equals(f.getString("selectedId"))&&e.optBoolean("dynamic",false)&&rows.length()<16){var copy=WorldFrames.copy(e);copy.remove("source");rows.put(copy);}}
        var out=new JSONObject().put("snapshotHash",f.getString("snapshotHash")).put("source",f.getJSONObject("source")).put("entityCount",f.getJSONArray("entities").length()).put("selectedId",f.getString("selectedId")).put("entities",rows).put("associations",f.getJSONArray("associations")).put("limits",f.getString("limits"));
        if(f.has("observationPlane")){var o=WorldFrames.copy(f.getJSONObject("observationPlane"));o.remove("geometry");out.put("observationPlane",o);}return out;
    }
    static JSONObject exported(JSONObject frame){return new JSONObject().put("format",VERSION).put("frame",frame).put("scope","Read-only source snapshot; no camera pixels. A checksum verifies bytes, not authority to replace native or observed state.");}
    static JSONObject verifyExport(JSONObject in){SpatialScene.keys(in,"format","frame","scope");if(!VERSION.equals(in.getString("format")))throw new IllegalArgumentException("Unknown spatial export format");var f=WorldFrames.copy(in.getJSONObject("frame"));String hash=f.getString("snapshotHash");f.remove("snapshotHash");if(!WorldFrames.hash(f).equals(hash))throw new IllegalStateException("Exported snapshot checksum differs");return new JSONObject().put("passed",true).put("snapshotHash",hash).put("entities",f.getJSONArray("entities").length()).put("scope","Checksum only; importing cannot grant native authority");}
}

